//
// The v1.0 specification documents the core validates against, embedded in
// flash (generated by tools/embed_spec_documents.py). Each is parsed on
// first use and then shared; parsing is thread-safe (function-local statics).

#pragma once

#include <memory>
#include <string_view>

#include "a2ui/json.h"
#include "a2ui/ref.h"

namespace a2ui {
namespace spec {

enum class Document : uint8_t {
  CommonTypesV1_0,      // specification/v1_0/json/common_types.json
  AgentToRendererV1_0,  // specification/v1_0/json/agent_to_renderer.json
  BasicCatalogV1,       // catalogs/basic/v1/catalog.json
};

/** The minified document text. */
std::string_view text(Document doc);

/** The parsed document, shared. Never null (the embedded text is valid JSON). */
Ref<const Json> parsed(Document doc);

/** The common types document of a normalized protocol version ("1.0"), or null. */
Ref<const Json> common_types(std::string_view protocol_version);

}  // namespace spec
}  // namespace a2ui
